//! Maintenance tasks for keeping cui-rs in step with upstream CUI.
//!
//!     cargo xtask update [REV]   move the CUI submodule (default: origin's HEAD) and regenerate
//!     cargo xtask bindgen        regenerate cui-sys/src/bindings.rs, cui_commit.txt and cui/src/icons.rs
//!     cargo xtask check          fail if the generated files are out of date (CI)
//!     cargo xtask coverage       list CUI functions the safe crate does not wrap yet

use std::fmt::Write as _;
use std::path::{Path, PathBuf};
use std::process::{exit, Command};

include!("../../cui-sys/bindgen_config.rs");

fn main() {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().to_path_buf();
    match args.first().map(String::as_str) {
        Some("update") => update(&root, args.get(1).map(String::as_str)),
        Some("bindgen") => write_all(&root),
        Some("check") => check(&root),
        Some("coverage") => coverage(&root),
        _ => {
            eprintln!("usage: cargo xtask <update [REV] | bindgen | check | coverage>");
            exit(2);
        }
    }
}

struct Generated {
    bindings: String,
    commit: String,
    icons: String,
}

fn paths(root: &Path) -> [PathBuf; 3] {
    [
        root.join("cui-sys/src/bindings.rs"),
        root.join("cui-sys/src/cui_commit.txt"),
        root.join("cui/src/icons.rs"),
    ]
}

fn generate(root: &Path) -> Generated {
    let sys = root.join("cui-sys");
    let bindings = cui_bindgen_builder(&sys)
        .generate()
        .expect("bindgen failed (is libclang installed?)")
        .to_string();
    let bindings = format!(
        "// Generated by `cargo xtask bindgen` from CUI {}. Do not edit.\n\n{bindings}",
        git(&sys.join("CUI"), &["rev-parse", "--short=7", "HEAD"])
    );
    let commit = git(&sys.join("CUI"), &["rev-parse", "HEAD"]);
    let header = std::fs::read_to_string(sys.join("CUI/include/cui/cui_icons.h")).unwrap();
    Generated { bindings, commit, icons: icons(&header) }
}

fn write_all(root: &Path) {
    let g = generate(root);
    let [b, c, i] = paths(root);
    std::fs::write(&b, g.bindings).unwrap();
    std::fs::write(&c, g.commit).unwrap();
    std::fs::write(&i, g.icons).unwrap();
    println!("wrote {}\nwrote {}\nwrote {}", b.display(), c.display(), i.display());
}

fn check(root: &Path) {
    let g = generate(root);
    let mut stale = false;
    for (path, want) in paths(root).iter().zip([g.bindings, g.commit, g.icons]) {
        if std::fs::read_to_string(path).ok().as_deref() != Some(want.as_str()) {
            eprintln!("out of date: {}", path.display());
            stale = true;
        }
    }
    if stale {
        eprintln!("run `cargo xtask bindgen` and commit the result");
        exit(1);
    }
    println!("generated files are up to date");
}

fn update(root: &Path, rev: Option<&str>) {
    let cui = root.join("cui-sys/CUI");
    let before = git(&cui, &["rev-parse", "--short", "HEAD"]);
    run(Command::new("git").current_dir(&cui).args(["fetch", "--tags", "origin"]));
    // CI checkouts of submodules may lack origin/HEAD; ask the remote.
    run(Command::new("git").current_dir(&cui).args(["remote", "set-head", "origin", "--auto"]));
    let target = rev.unwrap_or("origin/HEAD");
    run(Command::new("git").current_dir(&cui).args(["checkout", "--quiet", target]));
    let after = git(&cui, &["rev-parse", "--short", "HEAD"]);
    write_all(root);
    if before == after {
        println!("CUI already at {after}");
        return;
    }
    println!("\nCUI {before} -> {after}:");
    run(Command::new("git").current_dir(&cui).args(["log", "--oneline", &format!("{before}..{after}")]));
    println!("\nPublic header changes:");
    run(Command::new("git").current_dir(&cui).args(["diff", "--stat", &before, &after, "--", "include"]));
    println!("\nNext: cargo test, cargo xtask coverage, bump versions in cui-sys/Cargo.toml and CHANGELOG.md");
}

fn coverage(root: &Path) {
    let bindings = std::fs::read_to_string(root.join("cui-sys/src/bindings.rs")).unwrap();
    let mut safe = String::new();
    collect_rs(&root.join("cui/src"), &mut safe);
    let mut all = Vec::new();
    for line in bindings.lines() {
        if let Some(rest) = line.trim().strip_prefix("pub fn ") {
            let name: String = rest.chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
            all.push(name);
        }
    }
    all.sort();
    all.dedup();
    let missing: Vec<_> = all
        .iter()
        .filter(|f| !contains_ident(&safe, &format!("sys::{f}")))
        .collect();
    for f in &missing {
        println!("{f}");
    }
    eprintln!("\n{} of {} CUI functions wrapped ({} available raw through cui::sys)", all.len() - missing.len(), all.len(), missing.len());
}

fn contains_ident(haystack: &str, needle: &str) -> bool {
    haystack.match_indices(needle).any(|(i, _)| {
        let next = haystack[i + needle.len()..].chars().next();
        !matches!(next, Some(c) if c.is_alphanumeric() || c == '_')
    })
}

fn collect_rs(dir: &Path, out: &mut String) {
    for entry in std::fs::read_dir(dir).unwrap() {
        let path = entry.unwrap().path();
        if path.is_dir() {
            collect_rs(&path, out);
        } else if path.extension().is_some_and(|e| e == "rs") {
            out.push_str(&std::fs::read_to_string(&path).unwrap());
        }
    }
}

/// Turns `#define CUI_ICON_NAME "\xee\x81\xac"` lines into Rust string constants.
fn icons(header: &str) -> String {
    let mut out = String::from(
        "// Generated by `cargo xtask bindgen` from cui_icons.h. Do not edit.\n\
         //! Lucide icons (ISC license, https://lucide.dev) as UTF-8 strings.\n\
         //!\n\
         //! Each one works on its own or inside any label:\n\
         //! `ui.button(&format!(\"{} New project\", icons::PLUS))`.\n\n",
    );
    for line in header.lines() {
        let Some(rest) = line.strip_prefix("#define CUI_ICON_") else { continue };
        let mut parts = rest.split_whitespace();
        let (Some(name), Some(lit)) = (parts.next(), parts.next()) else { continue };
        let lit = lit.trim_matches('"');
        let mut bytes = Vec::new();
        let mut s = lit;
        while let Some(hex) = s.strip_prefix("\\x") {
            bytes.push(u8::from_str_radix(&hex[..2], 16).expect("bad icon escape"));
            s = &hex[2..];
        }
        assert!(s.is_empty(), "unexpected icon literal for {name}: {lit}");
        let text = String::from_utf8(bytes).expect("icon is not UTF-8");
        let escaped: String = text.chars().map(|c| format!("\\u{{{:x}}}", c as u32)).collect();
        writeln!(out, "pub const {name}: &str = \"{escaped}\";").unwrap();
    }
    out
}

fn git(dir: &Path, args: &[&str]) -> String {
    let out = Command::new("git").current_dir(dir).args(args).output().expect("git");
    String::from_utf8(out.stdout).unwrap().trim().to_owned()
}

fn run(cmd: &mut Command) {
    let status = cmd.status().expect("failed to spawn");
    if !status.success() {
        exit(status.code().unwrap_or(1));
    }
}
